import{E as e,F as t,q as n,w as r}from"./vue.runtime.esm-bundler-DZZTqpJU.js";t();var i={class:`markdown-body`},a={__name:`docker.zh`,setup(t,{expose:a}){return a({frontmatter:{}}),(t,a)=>(n(),r(`div`,i,[...a[0]||=[e(`<p>Docker 能够将应用程序打包并运行在一个称为容器（container）的松散隔离环境中。这种隔离性和安全性使你可以在同一台主机上同时运行多个容器。容器十分轻量，包含了运行应用所需的一切，因此你无需依赖主机上当前已安装的内容。你可以在工作时轻松地共享容器，并确保每一位共享对象都能获得以相同方式运行的相同容器。</p><h2>安装与资源</h2><ul><li>Docker Desktop（Mac、Linux、Windows）：<a href="https://docs.docker.com/desktop">https://docs.docker.com/desktop</a></li><li>使用 Docker 的示例项目：<a href="https://github.com/docker/awesome-compose">https://github.com/docker/awesome-compose</a></li><li>官方文档：<a href="https://docs.docker.com">https://docs.docker.com</a></li></ul><h2>通用命令</h2><p>启动 Docker 守护进程：</p><pre><code class="language-bash">dockerd
</code></pre><p>获取 Docker 帮助（适用于所有子命令，例如 <code>docker run --help</code>）：</p><pre><code class="language-bash">docker --help
</code></pre><p>显示系统级信息：</p><pre><code class="language-bash">docker info
</code></pre><p>显示 Docker 版本（客户端和服务端）：</p><pre><code class="language-bash">docker version
</code></pre><h2>镜像</h2><p>Docker 镜像是一种轻量、独立、可执行的软件包，包含运行应用所需的一切：代码、运行时、系统工具、系统库和设置。</p><p>从当前目录的 Dockerfile 构建镜像：</p><pre><code class="language-bash">docker build -t &lt;image_name&gt; .
</code></pre><p>不使用缓存构建镜像：</p><pre><code class="language-bash">docker build -t &lt;image_name&gt; . --no-cache
</code></pre><p>使用指定标签构建（例如 <code>myapp:v1.2</code>）：</p><pre><code class="language-bash">docker build -t &lt;image_name&gt;:&lt;tag&gt; .
</code></pre><p>列出本地镜像：</p><pre><code class="language-bash">docker images
</code></pre><p>为推送到镜像仓库给镜像打标签：</p><pre><code class="language-bash">docker tag &lt;image&gt; &lt;username&gt;/&lt;image&gt;:&lt;tag&gt;
</code></pre><p>删除镜像：</p><pre><code class="language-bash">docker rmi &lt;image_name&gt;
</code></pre><p>移除悬空（未使用）的镜像：</p><pre><code class="language-bash">docker image prune
</code></pre><p>移除所有未使用的镜像，而不仅仅是悬空镜像：</p><pre><code class="language-bash">docker image prune -a
</code></pre><p>显示镜像的各个层：</p><pre><code class="language-bash">docker history &lt;image_name&gt;
</code></pre><h2>Docker Hub</h2><p>Docker Hub 是一项用于查找和共享容器镜像的服务。了解更多请访问 <a href="https://hub.docker.com">https://hub.docker.com</a></p><p>登录 Docker Hub：</p><pre><code class="language-bash">docker login -u &lt;username&gt;
</code></pre><p>登出：</p><pre><code class="language-bash">docker logout
</code></pre><p>在 Docker Hub 中搜索镜像：</p><pre><code class="language-bash">docker search &lt;image_name&gt;
</code></pre><p>从 Docker Hub 拉取镜像：</p><pre><code class="language-bash">docker pull &lt;image_name&gt;
</code></pre><p>拉取指定标签的版本：</p><pre><code class="language-bash">docker pull &lt;image_name&gt;:&lt;tag&gt;
</code></pre><p>将镜像发布到 Docker Hub：</p><pre><code class="language-bash">docker push &lt;username&gt;/&lt;image_name&gt;
</code></pre><h2>容器</h2><p>容器是 Docker 镜像的运行时实例。无论基础设施如何，容器都会以相同的方式运行。容器将软件与其环境隔离，确保它在开发、预发布和生产环境中保持一致的运行效果。</p><h3>运行容器</h3><p>从镜像创建并运行容器：</p><pre><code class="language-bash">docker run &lt;image_name&gt;
</code></pre><p>使用自定义名称运行：</p><pre><code class="language-bash">docker run --name &lt;container_name&gt; &lt;image_name&gt;
</code></pre><p>在后台运行（分离模式）：</p><pre><code class="language-bash">docker run -d &lt;image_name&gt;
</code></pre><p>以交互方式运行并进入 shell：</p><pre><code class="language-bash">docker run -it &lt;image_name&gt; bash
</code></pre><p>容器退出时自动移除：</p><pre><code class="language-bash">docker run --rm &lt;image_name&gt;
</code></pre><p>将容器的端口发布到主机：</p><pre><code class="language-bash">docker run -p &lt;host_port&gt;:&lt;container_port&gt; &lt;image_name&gt;
</code></pre><p>设置环境变量：</p><pre><code class="language-bash">docker run -e KEY=value &lt;image_name&gt;
</code></pre><p>从文件加载环境变量：</p><pre><code class="language-bash">docker run --env-file ./env.list &lt;image_name&gt;
</code></pre><p>挂载命名卷：</p><pre><code class="language-bash">docker run -v &lt;volume_name&gt;:/path/in/container &lt;image_name&gt;
</code></pre><p>将当前目录进行绑定挂载：</p><pre><code class="language-bash">docker run -v $(pwd):/app &lt;image_name&gt;
</code></pre><p>设置重启策略（可选值：<code>no</code>、<code>on-failure</code>、<code>always</code>、<code>unless-stopped</code>）：</p><pre><code class="language-bash">docker run --restart unless-stopped &lt;image_name&gt;
</code></pre><p>连接到指定网络：</p><pre><code class="language-bash">docker run --network &lt;network_name&gt; &lt;image_name&gt;
</code></pre><h3>管理容器</h3><p>列出正在运行的容器：</p><pre><code class="language-bash">docker ps
</code></pre><p>列出所有容器（运行中和已停止）：</p><pre><code class="language-bash">docker ps -a
</code></pre><p>启动一个已停止的容器：</p><pre><code class="language-bash">docker start &lt;container_name&gt;
</code></pre><p>停止一个正在运行的容器：</p><pre><code class="language-bash">docker stop &lt;container_name&gt;
</code></pre><p>重启容器：</p><pre><code class="language-bash">docker restart &lt;container_name&gt;
</code></pre><p>移除一个已停止的容器：</p><pre><code class="language-bash">docker rm &lt;container_name&gt;
</code></pre><p>强制移除一个正在运行的容器：</p><pre><code class="language-bash">docker rm -f &lt;container_name&gt;
</code></pre><p>移除所有已停止的容器：</p><pre><code class="language-bash">docker container prune
</code></pre><p>重命名容器：</p><pre><code class="language-bash">docker rename &lt;old_name&gt; &lt;new_name&gt;
</code></pre><h3>检查与交互</h3><p>进入正在运行容器的 shell：</p><pre><code class="language-bash">docker exec -it &lt;container_name&gt; bash
</code></pre><p>对于不自带 bash 的精简镜像（例如 alpine），使用 <code>sh</code>：</p><pre><code class="language-bash">docker exec -it &lt;container_name&gt; sh
</code></pre><p>获取日志：</p><pre><code class="language-bash">docker logs &lt;container_name&gt;
</code></pre><p>持续跟踪日志（类似 <code>tail -f</code>）：</p><pre><code class="language-bash">docker logs -f &lt;container_name&gt;
</code></pre><p>仅显示最后 100 行：</p><pre><code class="language-bash">docker logs --tail 100 &lt;container_name&gt;
</code></pre><p>显示容器的底层详细信息（JSON）：</p><pre><code class="language-bash">docker inspect &lt;container_name&gt;
</code></pre><p>实时查看所有容器的资源使用统计：</p><pre><code class="language-bash">docker stats
</code></pre><p>显示容器内正在运行的进程：</p><pre><code class="language-bash">docker top &lt;container_name&gt;
</code></pre><p>从容器中复制文件出来：</p><pre><code class="language-bash">docker cp &lt;container_name&gt;:/path/in/container ./
</code></pre><p>将文件复制到容器中：</p><pre><code class="language-bash">docker cp ./local_file &lt;container_name&gt;:/path/
</code></pre><p>显示容器启动以来的文件系统变更：</p><pre><code class="language-bash">docker diff &lt;container_name&gt;
</code></pre><h2>卷</h2><p>卷（Volume）将数据持久化在容器的可写层之外，因此数据在容器被移除后仍然保留。</p><p>创建命名卷：</p><pre><code class="language-bash">docker volume create &lt;volume_name&gt;
</code></pre><p>列出卷：</p><pre><code class="language-bash">docker volume ls
</code></pre><p>显示卷的详细信息：</p><pre><code class="language-bash">docker volume inspect &lt;volume_name&gt;
</code></pre><p>移除卷：</p><pre><code class="language-bash">docker volume rm &lt;volume_name&gt;
</code></pre><p>移除所有未使用的卷：</p><pre><code class="language-bash">docker volume prune
</code></pre><p>将命名卷挂载到容器（由 Docker 管理）：</p><pre><code class="language-bash">docker run -v &lt;volume_name&gt;:/data &lt;image_name&gt;
</code></pre><p>将主机路径绑定挂载到容器：</p><pre><code class="language-bash">docker run -v $(pwd):/app &lt;image_name&gt;
</code></pre><p>使用 <code>--mount</code> 语法的等价绑定挂载：</p><pre><code class="language-bash">docker run --mount type=bind,src=$(pwd),dst=/app &lt;image_name&gt;
</code></pre><h2>网络</h2><p>同一网络中的容器可以通过容器名称相互访问。</p><p>列出网络：</p><pre><code class="language-bash">docker network ls
</code></pre><p>创建网络：</p><pre><code class="language-bash">docker network create &lt;network_name&gt;
</code></pre><p>显示网络详细信息：</p><pre><code class="language-bash">docker network inspect &lt;network_name&gt;
</code></pre><p>将正在运行的容器连接到网络：</p><pre><code class="language-bash">docker network connect &lt;network_name&gt; &lt;container_name&gt;
</code></pre><p>将容器从网络断开：</p><pre><code class="language-bash">docker network disconnect &lt;network_name&gt; &lt;container_name&gt;
</code></pre><p>移除网络：</p><pre><code class="language-bash">docker network rm &lt;network_name&gt;
</code></pre><p>移除所有未使用的网络：</p><pre><code class="language-bash">docker network prune
</code></pre><h2>Docker Compose</h2><p>Compose 通过单个 <code>compose.yaml</code>（或 <code>docker-compose.yml</code>）文件运行多容器应用。</p><p>启动所有服务（前台）：</p><pre><code class="language-bash">docker compose up
</code></pre><p>启动所有服务（分离模式）：</p><pre><code class="language-bash">docker compose up -d
</code></pre><p>启动前先重新构建镜像：</p><pre><code class="language-bash">docker compose up --build
</code></pre><p>停止并移除容器和网络：</p><pre><code class="language-bash">docker compose down
</code></pre><p>同时移除命名卷：</p><pre><code class="language-bash">docker compose down -v
</code></pre><p>列出项目中的服务：</p><pre><code class="language-bash">docker compose ps
</code></pre><p>持续跟踪所有服务的日志：</p><pre><code class="language-bash">docker compose logs -f
</code></pre><p>持续跟踪单个服务的日志：</p><pre><code class="language-bash">docker compose logs -f &lt;service&gt;
</code></pre><p>构建（或重新构建）服务：</p><pre><code class="language-bash">docker compose build
</code></pre><p>拉取服务镜像：</p><pre><code class="language-bash">docker compose pull
</code></pre><p>在正在运行的服务中打开 shell：</p><pre><code class="language-bash">docker compose exec &lt;service&gt; bash
</code></pre><p>在新容器中运行一次性命令：</p><pre><code class="language-bash">docker compose run --rm &lt;service&gt; &lt;command&gt;
</code></pre><p>重启单个服务：</p><pre><code class="language-bash">docker compose restart &lt;service&gt;
</code></pre><p>校验并查看解析后的 compose 文件：</p><pre><code class="language-bash">docker compose config
</code></pre><h2>系统与清理</h2><p>磁盘占用会迅速累积。以下命令可用于回收空间。</p><p>显示磁盘使用情况（镜像、容器、卷、构建缓存）：</p><pre><code class="language-bash">docker system df
</code></pre><p>移除已停止的容器、悬空镜像和未使用的网络：</p><pre><code class="language-bash">docker system prune
</code></pre><p>同时移除所有未使用的镜像（不仅仅是悬空镜像）：</p><pre><code class="language-bash">docker system prune -a
</code></pre><p>同时移除未使用的卷（具有破坏性——运行前请再三确认）：</p><pre><code class="language-bash">docker system prune -a --volumes
</code></pre><p>清理构建缓存：</p><pre><code class="language-bash">docker builder prune
</code></pre><h2>快速参考：常用标志</h2><table><thead><tr><th>标志</th><th>含义</th></tr></thead><tbody><tr><td><code>-d</code></td><td>分离模式（在后台运行）</td></tr><tr><td><code>-it</code></td><td>交互模式 + TTY（用于 shell）</td></tr><tr><td><code>--rm</code></td><td>容器退出时移除它</td></tr><tr><td><code>-p host:container</code></td><td>发布端口</td></tr><tr><td><code>-v src:dst</code></td><td>挂载卷或绑定挂载</td></tr><tr><td><code>-e KEY=value</code></td><td>环境变量</td></tr><tr><td><code>--name</code></td><td>指定容器名称</td></tr><tr><td><code>--network</code></td><td>连接到网络</td></tr><tr><td><code>--restart</code></td><td>重启策略（<code>no</code>、<code>on-failure</code>、<code>always</code>、<code>unless-stopped</code>）</td></tr></tbody></table>`,193)]]))}};export{a as default};